dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/c2ct/1?columns=phenotype",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry*",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "*"
        },
        {
          "label": "AA",
          "value": "AA"
        },
        {
          "label": "EA",
          "value": "EA"
        },
        {
          "label": "EU",
          "value": "EU"
        },
        {
          "label": "HS",
          "value": "HS"
        },
        {
          "label": "SA",
          "value": "SA"
        }
      ]
    },
    {
      "parameter": "annotation",
      "label": "Annotation*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/c2ct-tissue/4?columns=annotation",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/c2ct-tissue/4?columns=tissue",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "biosample",
      "label": "Biosample",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "csid",
      "label": "CS ID",
      "type": "input",
      "display": "false"
    }
  ],
  "visualizer collection": [
    {
      "sections": [
        "associations"
      ],
      "label": "Associated variants in viewing region"
    },
    {
      "sections": [
        "variant_links"
      ],
      "label": "SNP to gene links (grouped by target gene, colored by source)"
    },
    {
      "sections": [
        "gene_links"
      ],
      "label": "Tissue-specific epigenomic annotations across region (grouped by target gene, colored by source)"
    },
    {
      "sections": [
        "credible_sets"
      ],
      "label": "Credible sets in viewing region +-1MBP (grouped by method, colored by dataset)"
    },
    {
      "sections": [
        "regions"
      ],
      "label": "Annotations within tissue x viewing region (grouped by biosample, colored by source (method))"
    },
    {
      "sections": [
        "regions_other_tissues"
      ],
      "label": "Annotations in all tissues x viewing region (grouped by tissue, colored by source (method))"
    }
  ],
  "tab groups": [
    {
      "label": "Find Region of Interest",
      "sections": [
        {
          "section": "c2ct_phenotype_annotation",
          "label": "Credible sets overlapping by phenotype x ancestry x annotation"
        }
      ]
    },
    {
      "label": "credible variants",
      "sections": [
        {
          "section": "credible_sets",
          "label": "Credible sets in viewing region +-1MBP"
        }
      ]
    },
    {
      "label": "Variants",
      "sections": [
        {
          "section": "associations",
          "label": "Variants in viewing region"
        }
      ]
    },
    {
      "label": "Annotations within $tissue x $region",
      "sections": [
        {
          "section": "regions_other_tissues",
          "label": "Annotations in all tissues"
        },
        {
          "section": "regions",
          "label": "Annotations within tissue x viewing region"
        }
      ]
    },
    {
      "label": "SNP to gene links",
      "sections": [
        {
          "section": "gene_links",
          "label": "Tissue-specific epigenomic annotations across region"
        }
      ]
    },
    {
      "label": "SNP to gene links",
      "sections": [
        {
          "section": "variant_links",
          "label": "SNP to gene links"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "c2ct_phenotype_annotation",
      "header": "Credible sets overlapping $phenotype x $ancestry x $annotation",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/query/c2ct-annotation?q=$phenotype,$ancestry,$annotation&limit=20000",
        "continue url": "https://giant.hugeampkpnbi.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "phenotype",
          "ancestry",
          "annotation"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "clumpEnd",
              "-",
              "clumpStart"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd",
              "region length"
            ],
            "join by": [
              ":",
              "-",
              " (",
              "bp)"
            ]
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "split",
            "field name": [
              "lead chr",
              "position ref alt"
            ],
            "field to split": "leadSNP",
            "split by": [
              ":"
            ]
          },
          {
            "type": "split",
            "field name": [
              "Lead SNP position",
              "ref alt"
            ],
            "field to split": "position ref alt",
            "split by": [
              ":"
            ]
          },
          {
            "type": "split",
            "field name": [
              "lead ref",
              "lead alt"
            ],
            "field to split": "ref alt",
            "split by": [
              ":"
            ]
          },
          {
            "type": "join multi",
            "field name": "Lead SNP",
            "fields to join": [
              "lead chr",
              "Lead SNP position",
              "lead ref",
              "lead alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "Lead SNP"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "Lead SNP position"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionStart",
            "expression": [
              "Lead SNP position",
              "-",
              200000
            ],
            "note": ""
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionEnd",
            "expression": [
              "Lead SNP position",
              "+",
              200000
            ],
            "note": ""
          },
          {
            "type": "join multi",
            "field name": "Set region to Lead SNP +-200kb",
            "fields to join": [
              "chromosome",
              "regionStart",
              "regionEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Load annotation + tissue + biosample CS2CT",
            "fields to join": [
              "annotation",
              "tissue",
              "biosample"
            ],
            "join by": [
              ",",
              ","
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Total entropy",
            "raw field": "totalEntropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy",
            "raw field": "entropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy in",
            "raw field": "entropy_in",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy out",
            "raw field": "entropy_out",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Q",
            "raw field": "Q",
            "if no value": 0
          },
          {
            "type": "join multi",
            "field name": "Biosample:CS region",
            "fields to join": [
              "Biosample",
              "CS region"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Annotation bp",
            "raw field": "annot_bp",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy PP",
            "raw field": "entPP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy type",
            "raw field": "entropyType",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Lead SNP p-value",
            "raw field": "leadSNPPValue",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Overlap lead SNP",
            "raw field": "overlapLeadSNP",
            "if no value": "N/A"
          },
          {
            "type": "replace characters",
            "field name": "Ancestry",
            "raw field": "ancestry",
            "replace": [
              {
                "from": "Mixed",
                "to": "*"
              }
            ]
          },
          {
            "type": "join multi",
            "field name": "Find more CS overlapping same tissue",
            "fields to join": [
              "phenotype",
              "Ancestry",
              "Annotation",
              "Tissue"
            ],
            "join by": [
              ",",
              ",",
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Find more CS overlapping same biosample",
            "fields to join": [
              "phenotype",
              "Ancestry",
              "Annotation",
              "Tissue",
              "Biosample"
            ],
            "join by": [
              ",",
              ",",
              ",",
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "View variants in CS",
            "fields to join": [
              "phenotype",
              "Ancestry",
              "CS ID"
            ],
            "join by": [
              ",",
              ","
            ]
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "Lead SNP",
          "Lead SNP p-value",
          "PPO",
          "Entropy",
          "Entropy in",
          "Entropy out",
          "Find more CS overlapping same tissue",
          "Find more CS overlapping same biosample",
          "View variants in CS",
          "Set region to Lead SNP +-200kb"
        ],
        "star column": "Variant ID",
        "column formatting": {
          "Set region to Lead SNP +-200kb": {
            "type": [
              "set parameter"
            ],
            "label": "Set",
            "target sections": [
              {
                "section": "all",
                "label": "Set region",
                "parameter": [
                  "region"
                ]
              }
            ]
          },
          "View variants in CS": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "label": "Variants in CS",
              "data point": {
                "type": "bioindex",
                "url": "https://giant.hugeampkpnbi.org/api/bio/",
                "index": "credible-variants",
                "parameters": [
                  "phenotype",
                  "ancestry",
                  "csid"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "star column": "Variant ID",
                "data convert": [
                  {
                    "type": "join multi",
                    "field name": "Variant ID",
                    "fields to join": [
                      "chromosome",
                      "position",
                      "reference",
                      "alt"
                    ],
                    "join by": [
                      ":",
                      "_",
                      "/"
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "CV Variant ID",
                    "raw field": "Variant ID"
                  },
                  {
                    "type": "join multi",
                    "field name": "Ref/Alt",
                    "fields to join": [
                      "reference",
                      "alt"
                    ],
                    "join by": [
                      "/"
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "PPO",
                    "raw field": "posteriorProbability"
                  },
                  {
                    "type": "raw",
                    "field name": "CS ID",
                    "raw field": "credibleSetId"
                  },
                  {
                    "type": "raw",
                    "field name": "Dataset",
                    "raw field": "dataset"
                  },
                  {
                    "type": "raw",
                    "field name": "Method",
                    "raw field": "method"
                  },
                  {
                    "type": "raw",
                    "field name": "EAF",
                    "raw field": "eaf"
                  },
                  {
                    "type": "raw",
                    "field name": "PMID",
                    "raw field": "pmid"
                  },
                  {
                    "type": "raw",
                    "field name": "Position",
                    "raw field": "position"
                  }
                ],
                "top rows": [
                  "Variant ID",
                  "PPO",
                  "CS ID",
                  "Dataset",
                  "EAF",
                  "Method",
                  "Position",
                  "PMID"
                ],
                "locus field": "CS region",
                "column formatting": {
                  "PPO": {
                    "type": [
                      "scientific notation"
                    ]
                  }
                }
              }
            }
          },
          "Find more CS overlapping same tissue": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "label": "CS overlapping same tissue",
              "data point": {
                "type": "bioindex",
                "url": "https://giant.hugeampkpnbi.org/api/bio/",
                "index": "c2ct-tissue",
                "parameters": [
                  "phenotype",
                  "ancestry",
                  "annotation",
                  "tissue"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Annotation",
                    "raw field": "annotation",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Tissue",
                    "raw field": "tissue"
                  },
                  {
                    "type": "raw",
                    "field name": "Biosample",
                    "raw field": "biosample"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  },
                  {
                    "type": "raw",
                    "field name": "CS ID",
                    "raw field": "credibleSetId"
                  },
                  {
                    "type": "raw",
                    "field name": "chromosome",
                    "raw field": "chromosome"
                  },
                  {
                    "type": "calculate",
                    "calculation type": "math",
                    "field name": "region length",
                    "expression": [
                      "clumpEnd",
                      "-",
                      "clumpStart"
                    ],
                    "note": "required to get clumped region center"
                  },
                  {
                    "type": "join multi",
                    "field name": "CS region (length)",
                    "fields to join": [
                      "chromosome",
                      "clumpStart",
                      "clumpEnd",
                      "region length"
                    ],
                    "join by": [
                      ":",
                      "-",
                      " (",
                      "bp)"
                    ]
                  },
                  {
                    "type": "join multi",
                    "field name": "CS region",
                    "fields to join": [
                      "chromosome",
                      "clumpStart",
                      "clumpEnd"
                    ],
                    "join by": [
                      ":",
                      "-"
                    ]
                  },
                  {
                    "type": "split",
                    "field name": [
                      "lead chr",
                      "position ref alt"
                    ],
                    "field to split": "leadSNP",
                    "split by": [
                      ":"
                    ]
                  },
                  {
                    "type": "split",
                    "field name": [
                      "Lead SNP position",
                      "ref alt"
                    ],
                    "field to split": "position ref alt",
                    "split by": [
                      ":"
                    ]
                  },
                  {
                    "type": "split",
                    "field name": [
                      "lead ref",
                      "lead alt"
                    ],
                    "field to split": "ref alt",
                    "split by": [
                      ":"
                    ]
                  },
                  {
                    "type": "join multi",
                    "field name": "Lead SNP",
                    "fields to join": [
                      "lead chr",
                      "Lead SNP position",
                      "lead ref",
                      "lead alt"
                    ],
                    "join by": [
                      ":",
                      "_",
                      "/"
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "Variant ID",
                    "raw field": "Lead SNP"
                  },
                  {
                    "type": "raw",
                    "field name": "Position",
                    "raw field": "Lead SNP position"
                  },
                  {
                    "type": "calculate",
                    "calculation type": "math",
                    "field name": "regionStart",
                    "expression": [
                      "Lead SNP position",
                      "-",
                      200000
                    ],
                    "note": ""
                  },
                  {
                    "type": "calculate",
                    "calculation type": "math",
                    "field name": "regionEnd",
                    "expression": [
                      "Lead SNP position",
                      "+",
                      200000
                    ],
                    "note": ""
                  },
                  {
                    "type": "join multi",
                    "field name": "View variants in CS & Lead SNP +-200kb",
                    "fields to join": [
                      "CS ID",
                      "chromosome",
                      "regionStart",
                      "regionEnd"
                    ],
                    "join by": [
                      ",",
                      ":",
                      "-"
                    ]
                  },
                  {
                    "type": "join multi",
                    "field name": "Load annotation + tissue + biosample CS2CT",
                    "fields to join": [
                      "annotation",
                      "tissue",
                      "biosample"
                    ],
                    "join by": [
                      ",",
                      ","
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "PPO",
                    "raw field": "posteriorProbability",
                    "if no value": 0
                  },
                  {
                    "type": "raw",
                    "field name": "Total entropy",
                    "raw field": "totalEntropy",
                    "if no value": 0
                  },
                  {
                    "type": "raw",
                    "field name": "Entropy",
                    "raw field": "entropy",
                    "if no value": 0
                  },
                  {
                    "type": "raw",
                    "field name": "Entropy in",
                    "raw field": "entropy_in",
                    "if no value": 0
                  },
                  {
                    "type": "raw",
                    "field name": "Entropy out",
                    "raw field": "entropy_out",
                    "if no value": 0
                  },
                  {
                    "type": "raw",
                    "field name": "Q",
                    "raw field": "Q",
                    "if no value": 0
                  },
                  {
                    "type": "join multi",
                    "field name": "Biosample:CS region",
                    "fields to join": [
                      "Biosample",
                      "CS region"
                    ],
                    "join by": [
                      ":"
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "Annotation bp",
                    "raw field": "annot_bp",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Entropy PP",
                    "raw field": "entPP",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Entropy type",
                    "raw field": "entropyType",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Lead SNP p-value",
                    "raw field": "leadSNPPValue",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Overlap lead SNP",
                    "raw field": "overlapLeadSNP",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Number of overlapping SNPs in CS",
                    "raw field": "varOverlap",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "SNPs in CS",
                    "raw field": "varTotal",
                    "if no value": "N/A"
                  }
                ],
                "top rows": [
                  "Tissue",
                  "Biosample",
                  "Source",
                  "SNPs in CS",
                  "Lead SNP",
                  "Lead SNP p-value",
                  "PPO",
                  "Entropy",
                  "Entropy in",
                  "Entropy out"
                ],
                "column formatting": {
                  "PPO": {
                    "type": [
                      "scientific notation"
                    ]
                  },
                  "Entropy": {
                    "type": [
                      "scientific notation"
                    ]
                  },
                  "Entropy in": {
                    "type": [
                      "scientific notation"
                    ]
                  },
                  "Entropy out": {
                    "type": [
                      "scientific notation"
                    ]
                  }
                }
              },
              "share parent filters": true,
              "visualizers": {
                "wrapper type": "tabs",
                "visualizers": [
                  {
                    "label": "PPO vs Entropy",
                    "type": "scatter plot",
                    "star key": "Biosample:CS region",
                    "render type": "single plot",
                    "group by": "Phenotype",
                    "color by": "Source",
                    "x axis field": "Entropy",
                    "x axis label": "Entropy",
                    "y axis field": "PPO",
                    "y axis label": "PPO",
                    "ticks decimal point": "4",
                    "render by": "Biosample:CS region",
                    "hover content": [
                      "PPO",
                      "Entropy",
                      "Total entropy"
                    ],
                    "height": 150,
                    "width": 450,
                    "plot margin": {
                      "left": 60,
                      "right": 20,
                      "top": 40,
                      "bottom": 50,
                      "bump": 5
                    }
                  },
                  {
                    "label": "PPO vs Entropy in",
                    "type": "scatter plot",
                    "star key": "Biosample:CS region",
                    "render type": "single plot",
                    "group by": "Phenotype",
                    "color by": "Source",
                    "x axis field": "Entropy in",
                    "x axis label": "Entropy in",
                    "y axis field": "PPO",
                    "y axis label": "PPO",
                    "ticks decimal point": "4",
                    "render by": "Biosample:CS region",
                    "hover content": [
                      "PPO",
                      "Entropy in",
                      "Total entropy"
                    ],
                    "height": 150,
                    "width": 450,
                    "plot margin": {
                      "left": 60,
                      "right": 20,
                      "top": 40,
                      "bottom": 50,
                      "bump": 5
                    }
                  },
                  {
                    "label": "PPO vs Entropy out",
                    "type": "scatter plot",
                    "star key": "Biosample:CS region",
                    "render type": "single plot",
                    "group by": "Phenotype",
